import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';let input='';for await(const c of process.stdin)input+=c;const cfg=JSON.parse(input);
const {chromium}=await import(pathToFileURL(cfg.module+'/index.mjs').href);const browser=await chromium.launch({headless:true,...(cfg.executable?{executablePath:cfg.executable}:{})});
try{const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.status()>=400)errors.push('HTTP '+r.status()+' '+new URL(r.url()).pathname)});await page.goto(cfg.url);for(const [id,api,expected] of cfg.rows){const node=page.locator(`[data-probe="${id}${api.slice(0,2)}"]`).filter({hasNotText:'pending'});try{await node.waitFor({timeout:15000})}catch(e){throw new Error(`${id} ${api}: ${errors.join('; ')}: ${e.message}`)}assert.deepEqual(JSON.parse(await node.textContent()),JSON.parse(expected),`${id} ${api}`);}for(const api of ['59','62','67']){const node=page.locator(`[data-probe="proxy${api}"]`);await node.filter({hasText:/^Query$/}).waitFor({timeout:15000});assert.equal(await node.textContent(),'Query');}assert.deepEqual(errors,[]);}finally{await browser.close();}
